// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address logger, bool status) public {
        // Only address(0) passes the onlyOwner modifier (_contractOwner is unset).
        vm.assume(logger != address(0));

        vm.prank(address(0));
        c.setApprovedLogger(logger, status);

        // General rule: the granted logger address is approved exactly as requested.
        assertTrue(c.approvedLoggers(logger) == status);
    }
}
